<?php
declare(strict_types=1);
if (PHP_SAPI!=='cli') exit(1);
require dirname(__DIR__).'/app/Support/SchemaCapabilities.php';
require dirname(__DIR__).'/app/Services/AdminDashboard.php';
use Divigamana\Services\AdminDashboard;
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$db->exec('CREATE TABLE users (id INTEGER PRIMARY KEY, mobile_e164 TEXT, account_status TEXT, phone_verified_real INTEGER, ideamart_subscriber_id TEXT, mspace_subscriber_id TEXT, created_at TEXT, last_login_at TEXT, first_login_at TEXT)');
$db->exec('CREATE TABLE audit_events (id INTEGER PRIMARY KEY, user_id INTEGER, event_type TEXT, created_at TEXT)');
$db->exec('CREATE TABLE user_subscriptions (id INTEGER PRIMARY KEY, user_id INTEGER, provider TEXT, status TEXT, provider_status TEXT, starts_at TEXT, ends_at TEXT, accepted_at TEXT, is_simulated INTEGER NOT NULL DEFAULT 0)');
$db->exec('CREATE TABLE payment_transactions (id INTEGER PRIMARY KEY, user_id INTEGER, status TEXT, amount DECIMAL, currency TEXT, provider TEXT, is_simulated INTEGER NOT NULL DEFAULT 0)');
$insert=$db->prepare('INSERT INTO users (id,mobile_e164,account_status,phone_verified_real,ideamart_subscriber_id,mspace_subscriber_id,created_at,last_login_at) VALUES (?,?,?,?,?,?,?,?)');
$insert->execute([1,'+94771234567','active',1,'idea-1',null,'2026-01-01 10:00:00',null]);
$insert->execute([2,'+94711234567','blocked',1,null,'mspace-2','2026-01-02 10:00:00',null]);
$insert->execute([3,'+94751234567','active',0,null,null,'2026-01-03 10:00:00',null]);
$sub=$db->prepare('INSERT INTO user_subscriptions (id,user_id,provider,status,starts_at,ends_at,accepted_at) VALUES (?,?,?,?,?,?,?)');
$before=date('Y-m-d H:i:s',time()-3600); $after=date('Y-m-d H:i:s',time()+3600);
$sub->execute([1,1,'ideamart','active',$before,$after,$before]);
$sub->execute([2,1,'ideamart','cancelled',$before,$after,$before]);
$sub->execute([3,2,'mspace','active',$before,$after,$before]);
$sub->execute([4,3,'ideamart','active','2020-01-01 00:00:00','2020-01-02 00:00:00',$before]);
$reporter=new AdminDashboard($db);
$filters=['from'=>'','to'=>'','provider'=>'','verification'=>'','search'=>''];
$r=$reporter->report($filters);
function expect(bool $condition,string $label): void { if (!$condition) { fwrite(STDERR,"FAIL $label\n"); exit(1); } echo "PASS $label\n"; }
expect((int)$r['summary']['total']===3 && (int)$r['summary']['active']===2 && (int)$r['summary']['inactive']===0 && (int)$r['summary']['blocked']===1,'summary counts any active subscription and excludes blocked accounts');
$directory=['from'=>'2026-01-01','to'=>'2026-01-01','provider'=>'','verification'=>'','search'=>'','status'=>'active','day'=>''];
$allDates=$reporter->report(AdminDashboard::directoryFilters($directory));
expect($allDates['count']===2 && (int)$allDates['summary']['active']===2,'active directory defaults to all join dates and matches overview');
$directory['day']='2026-01-01';
expect($reporter->report(AdminDashboard::directoryFilters($directory))['count']===1,'selecting a join date narrows the active directory');
$directory['search']='94751234567';
expect($reporter->report(AdminDashboard::directoryFilters($directory))['count']===1,'phone search spans all dates even when a join date is selected');
$by=[]; foreach ($r['funnel'] as $row) $by[$row['provider']]=$row;
expect((int)$by['dialog']['total']===1 && (int)$by['dialog']['active']===1 && (int)$by['mobitel']['active']===0 && (int)$by['airtel']['verified']===0,'provider funnel uses mobile prefixes and excludes blocked accounts from active');
expect((int)$r['verification']['ideamart']===1 && (int)$r['verification']['mspace']===1 && count($r['subscriptions'])===3,'verification and rolling subscription groups');
$db->exec("INSERT INTO audit_events VALUES (1,1,'login_success','2026-01-02 10:00:00'),(2,1,'login_success','2026-01-03 10:00:00')");
$daily=$reporter->report(array_merge($filters,['day'=>'2026-01-02']));
expect($daily['dailyNew']===1 && $daily['dailyLogins']===1,'daily counts use the selected day and recorded login events');
expect($r['subscriptionCount']===4 && count($r['subscriptionRows'])===4 && $r['subscriptionRows'][0]['mobile_e164']==='+94751234567' && $r['subscriptionRows'][0]['accepted_at']===$before,'subscription activity includes time and mobile in newest-first order');
$filters=['from'=>'2026-01-02','to'=>'2026-01-02','provider'=>'mobitel','verification'=>'mspace','search'=>'9471123'];
$r=$reporter->report($filters);
expect($r['count']===1 && $r['users'][0]['mobile_e164']==='+94711234567','date, provider, verification and number filters combine');
expect((int)$r['verification']['total']===3,'user filters do not affect the verification report');
$r=$reporter->report($filters,1,['from'=>'2026-01-01','to'=>'2026-01-01']);
expect((int)$r['verification']['total']===1 && (int)$r['verification']['ideamart']===1 && $r['count']===1,'verification report date range is independent');
$filters['verification']='unverified';
expect($reporter->report($filters)['count']===0,'verification filter excludes other states');
for ($i=4;$i<=30;$i++) $insert->execute([$i,'+9477'.str_pad((string)$i,7,'0',STR_PAD_LEFT),'active',0,null,null,'2026-01-04 10:00:00',null]);
$r=$reporter->report(['from'=>'','to'=>'','provider'=>'','verification'=>'','search'=>''],2);
expect($r['pages']===2 && count($r['users'])===5,'user directory paginates');

$sub->execute([5,1,'ideamart','active',$before,$after,date('Y-m-d H:i:s',time()-90000)]);
for ($i=6;$i<=31;$i++) $sub->execute([$i,1,'ideamart','active',$before,$after,$before]);
$r=$reporter->report(['from'=>'','to'=>'','provider'=>'','verification'=>'','search'=>''],1,[],2);
expect($r['subscriptionCount']===30 && $r['subscriptionPages']===2 && count($r['subscriptionRows'])===5,'last-24-hours activity excludes older records and paginates');
